import {beginReport,restoreReport,recordAction,metrics,exportReport,reportText} from './report.mjs?v=4';
import {cards,relics,cardCost,recoveryCount,fresh,apply,options,damage,assertState} from './rules.mjs?v=4';
import {esc,num,ratio,icon,button as btn,renderGame,renderReward,changes} from './view.mjs?v=4';
const root=document.querySelector('#app'),menu=document.querySelector('#menu'),choice=document.querySelector('#choice'),KEY='shanfara-raid-v1',COACH='shanfara-raid-coach-v2',LAST_REPORT='shanfara-raid-last-report-v1';
let s=fresh(true),selection=null,pending=null,lesson=4,feedback='',returnFocus=null,runReport=null,activeReport=null;
try{const saved=JSON.parse(localStorage.getItem(KEY));if([1,2].includes(saved?.v)&&['title','play','reward','end'].includes(saved.screen)&&['approach','strike','retreat','duel','end'].includes(saved.phase)){const { _run, ...gameState }=saved;assertState(gameState);s=gameState;runReport=restoreReport(_run,s);}if(!localStorage.getItem(COACH)&&s.turn===1&&s.phase==='approach')lesson=0;}catch{}
if(s.screen!=='title'&&!runReport)runReport=beginReport(s);
function persist(){try{localStorage.setItem(KEY,JSON.stringify({...s,_run:runReport}));if(lesson===4)localStorage.setItem(COACH,'done');}catch{}}
const focus=selector=>root.querySelector(selector)?.focus({preventScroll:true});
function dismiss(){if(choice.open)choice.close();selection=null;pending=null;render();if(returnFocus)focus(returnFocus);}
function animateFeedback(before,after,a,sourceRect){const reduce=globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches;const flash=(selector)=>root.querySelector(selector)?.animate?.([{outline:'2px solid #f2c16f',filter:'brightness(1.3)'},{outline:'2px solid transparent',filter:'brightness(1)'}],{duration:500,easing:'ease-out'});
 if(reduce)return;
 if(before.hp!==after.hp)flash('[data-feedback="hp"]');if(before.progress!==after.progress||before.phase!==after.phase)flash('[data-feedback="progress"]');if(before.rescue!==after.rescue)flash('[data-feedback="friend"]');if(before.guards!==after.guards)flash('[data-feedback="guard"]');if(before.ap!==after.ap)flash('[data-feedback="ap"]');if(damage(before)!==damage(after))flash('[data-feedback="damage"]');
 if(reduce||!sourceRect||a.type!=='play')return;const dest=root.querySelector(`[data-queued="${a.card}"]`)?.getBoundingClientRect?.();if(!dest||!sourceRect.width)return;const ghost=document.createElement('span');ghost.className='card-flight';ghost.textContent=cards[a.card].name;Object.assign(ghost.style,{left:sourceRect.left+'px',top:sourceRect.top+'px',width:sourceRect.width+'px',height:sourceRect.height+'px'});document.body.append(ghost);const anim=ghost.animate?.([{transform:'translate(0,0) scale(1)',opacity:1},{transform:`translate(${dest.left-sourceRect.left}px,${dest.top-sourceRect.top}px) scale(.5)`,opacity:0}],{duration:360,easing:'cubic-bezier(.2,.7,.2,1)'});if(anim)anim.onfinish=()=>ghost.remove();else ghost.remove();}
function dispatch(a){const before=s,source=root.querySelector(`[data-card="${a.card}"]`)?.getBoundingClientRect?.();s=apply(s,a);assertState(s);runReport=recordAction(runReport,before,a,s);if(s.screen==='end'){try{localStorage.setItem(LAST_REPORT,JSON.stringify(runReport));}catch{}}if(a.type==='play'){feedback=s.relic==='blade'&&a.card==='knife'?`«النصل» بقي في يدك · بقي ${num(s.ap)} فعل`:`«${cards[a.card].name}» في طابور الاستعادة · بقي ${num(s.ap)} فعل`;if(lesson<2)lesson=2;else if(lesson===2)lesson=3;}else if(a.type==='end'){feedback=`${before.queue.length?'عادت «'+before.queue.slice(0,recoveryCount(before)).map(id=>cards[id].name).join(' + ')+'» إلى يدك. ':''}${before.hp>s.hp?'خسرت '+num(before.hp-s.hp)+' صحة.':'لم تتلقَّ ضررًا.'}`;lesson=4;}else if(a.type==='relic')feedback=`أثرك: ${relics[s.relic].name}. اهزم الحارس أو اعبر الممر.`;else if(a.type==='retreat')feedback=s.rescue>=3?'بدأتما العودة إلى المخبأ.':'بدأت العودة؛ بقي رفيقك عند القافلة.';else feedback='';if(choice.open)choice.close();selection=null;pending=null;persist();render();animateFeedback(before,s,a,source);focus(s.screen==='reward'?'[data-relic]':s.screen==='end'?'[data-action="report"]':a.type==='end'?'[data-card]:not(:disabled)':'[data-action="end"]');}
function openChoice(){if(!choice.open)choice.showModal();choice.querySelector('[data-action="confirm"]:not(:disabled),[data-target],button')?.focus({preventScroll:true});}
function showCard(id){if(!options(s,id).length)return;returnFocus=`[data-card="${id}"]`;selection=id;const opts=options(s,id);pending=opts.length===1?{type:'play',card:id,target:opts[0].target}:null;if(lesson===0&&id==='run')lesson=1;render();renderChoice();openChoice();}
function renderChoice(){if(!selection&&!pending)return;const opts=selection?options(s,selection):[];const n=pending?apply(s,pending):null;const actionNames={step:'تقدّم خطوة',retreat:'بدء الانسحاب',drop:'ترك الغنيمة',end:'إنهاء الدور',assist:'مساندة الرفيق',relic:relics[pending?.relic]?.name||'اختر أثرك'};
 const title=selection?cards[selection].name:actionNames[pending?.type]||'اختر الحركة';
 choice.innerHTML=`<div class="sheet-header"><h2>${selection?icon(selection):''}${title}</h2>${btn('×','cancel','icon-button')}</div>${selection?'<p class="sheet-subtitle">'+(opts.length>1?'اختر الاستخدام':'تكلفة الاستخدام: '+num(cardCost(s,selection))+' فعل')+'</p>':''}${pending?.type==='relic'?`<p class="single-effect">${relics[pending.relic].rule}</p>`:''}${opts.length>1?`<div class="choices">${opts.map(o=>`<button data-target="${o.target}" class="choice ${pending?.target===o.target?'chosen':''}" aria-pressed="${pending?.target===o.target}"><span><strong>${o.label}</strong><small>${o.detail}</small></span><i>${pending?.target===o.target?'✓':'○'}</i></button>`).join('')}</div>`:opts.length===1?`<p class="single-effect">${opts[0].label}<small>${opts[0].detail}</small></p>`:''}${n?`<div class="preview"><div class="deltas">${changes(s,n,pending)}</div>${pending.type==='retreat'&&s.rescue<3&&s.friendHp>0?'<p class="danger">سيبقى رفيقك هنا.</p>':''}${pending.type==='end'&&s.ap>0?`<p>ستترك ${num(s.ap)} من أفعالك دون استخدام.</p>`:''}${n.screen==='end'?`<p class="${n.outcome==='dead'?'danger':'good'}">${n.outcome==='dead'?'هذه الحركة تنهي حياتك':n.screen==='reward'?'تختار مكافأتك ثم تواجه حارس الممر':'تصل للمخبأ وتنتهي الجولة'}</p>`:pending.type==='end'?`<div class="forecast-change">الصحة بعد الدور ${ratio(n.hp,16)}</div>`:`<div class="forecast-change"><span>ضرر نهاية الدور</span><bdi dir="ltr">${num(damage(s))} → ${num(damage(n))}</bdi></div>`}${pending.type==='play'?`<small>${s.relic==='blade'&&pending.card==='knife'?'النصل يبقى جاهزًا في يدك':`«${cards[pending.card].name}» تدخل الطابور · ترتيبها ${num(n.queue.indexOf(pending.card)+1)}`}</small>`:''}</div>`:'<p class="choose-prompt">اختر أحد الاستخدامات لتشاهد نتيجته.</p>'}<div class="sheet-footer">${btn(pending?.type==='end'?'أنهِ الدور':pending?.type==='retreat'?'ابدأ العودة':pending?.type==='relic'?'اختره وابدأ المواجهة':selection?'تنفيذ · '+num(cardCost(s,selection))+' فعل':'تنفيذ','confirm','primary',!pending)}${btn('إلغاء','cancel','secondary')}</div>`;}
function info(title,text){menu.innerHTML=`<div class="sheet-header"><h2>${title}</h2>${btn('×','close','icon-button')}</div><p class="info-copy">${text}</p>${btn('فهمت','close','primary')}`;menu.showModal();menu.querySelector('button')?.focus();}
function help(){menu.innerHTML=`<div class="sheet-header"><h2>طريق العودة</h2>${btn('×','close','icon-button')}</div>${btn('أكمل الغارة','close','primary')}${btn('جولة تعليمية جديدة','teach')}${btn('غارة جديدة','restart')}${s.screen==='end'?btn('تقرير هذه الجولة','report'):btn('تقرير آخر جولة مكتملة','last-report')}<details><summary>البطاقات والاستعادة</summary>${s.relic?`<p class="good">أثرك: ${relics[s.relic].rule}</p>`:''}<p>فعلان في كل دور. البطاقة المستخدمة تدخل آخر الطابور، وأول بطاقة تعود عند نهاية الدور. البطاقات الأخرى تبقى في يدك.</p></details><details><summary>الغارة والمطاردة</summary><p>بلوغ الزاد يحتاج ٤ خطوات، وإنقاذ الرفيق يحتاج ٣. القافلة تبتعد خطوة كل دور وتغادر بعد ٥ أدوار. الوصول للمخبأ يحتاج ٦ خطوات. كل ٣ إنذار تزيد الضرر ١.</p></details><details><summary>سجل الحركات</summary>${s.log.map(t=>`<p>${esc(t)}</p>`).join('')||'<p>لم تبدأ الغارة بعد.</p>'}</details><small>غارة تخييلية مستوحاة من أخبار الشنفرى.</small><p><a href="../exile/archive-v3/">النموذج السابق</a></p>`;menu.showModal();menu.querySelector('button')?.focus();}

function showReport(record){if(!record){info('لا يوجد تقرير بعد','ابدأ جولة جديدة، ثم افتح تقريرها عند النهاية.');return;}activeReport=record;const m=metrics(record),completed=record.final.screen==='end';menu.innerHTML=`<div class="sheet-header"><h2>تقرير الرن</h2>${btn('×','close','icon-button')}</div><p class="report-coverage ${record.coverage==='complete'?'good':'danger'}">${record.coverage==='complete'?'سجل كامل من بداية الجولة':'سجل جزئي: الجولة بدأت قبل تفعيل التسجيل'}</p><div class="report-metrics"><span>القرارات المسجّلة <b>${num(m.recordedDecisions)}</b></span><span>الضرر المسجّل <b>${num(m.recordedDamageTaken)}</b></span><span>أفعال تركتها بنهاية الدور <b>${num(m.unusedActionsAtTurnEnd)}</b></span></div><p class="report-instruction">انسخ التقرير وأرسله هنا في المحادثة لتحليل قرارات الجولة وتوازن اللعبة.</p>${btn('نسخ التقرير للتحليل','copy-report','primary')}${btn('تنزيل ملف التقرير JSON','download-report','secondary')}<p id="report-status" role="status" aria-live="polite"></p><details><summary>عرض التقرير كاملًا</summary><textarea id="report-text" readonly dir="auto" aria-label="تقرير الجولة القابل للنسخ">${esc(reportText(record))}</textarea></details><details><summary>تسلسل الحركات (${num(record.events.length)})</summary><ol class="report-timeline">${record.events.map(e=>`<li><span>دور ${num(e.before.turn)} · ${esc(e.label)}</span><small>الصحة <bdi dir="ltr">${num(e.before.hp)} → ${num(e.after.hp)}</bdi> · ضرر النهاية <bdi dir="ltr">${num(e.incomingBefore)} → ${num(e.incomingAfter)}</bdi></small></li>`).join('')||'<li>لا توجد حركات مسجّلة لهذه الجولة القديمة.</li>'}</ol></details><small>${completed?'':'هذه الجولة لم تنتهِ بعد. '}التقرير لا يُرسل تلقائيًا. يُحفظ آخر تقرير مكتمل على هذا الجهاز.</small>`;if(!menu.open)menu.showModal();menu.querySelector('[data-action="copy-report"]')?.focus();}
async function copyReport(){const status=menu.querySelector('#report-status');try{if(!globalThis.navigator?.clipboard?.writeText)throw Error('Clipboard unavailable');await navigator.clipboard.writeText(reportText(activeReport));if(status)status.textContent='تم النسخ. ارجع للمحادثة والصق التقرير.';}catch{const box=menu.querySelector('#report-text');const details=box?.closest?.('details');if(details)details.open=true;box?.focus();box?.select();if(status)status.textContent='تعذر النسخ التلقائي. النص محدد أدناه؛ انسخه يدويًا، أو نزّل ملف JSON.';}}
function downloadReport(){if(!activeReport)return;const blob=new Blob([JSON.stringify(exportReport(activeReport),null,2)],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`shanfara-run-${activeReport.runId}.json`;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);const status=menu.querySelector('#report-status');if(status)status.textContent='جهّزنا ملف التقرير للتنزيل. أرفقه في المحادثة للتحليل.';}

const results={full:['عاد الزاد، وعاد الرفيق','نجوتما بالغنيمة.'],loot:['عدت بالغنيمة وحدك','بلغت المخبأ بالزاد، وبقي رفيقك خلفك.'],friend:['عدتما بلا غنيمة','خرج رفيقك حيًّا. القافلة احتفظت بالزاد.'],alone:['نجوت وحدك','وصلت المخبأ؛ خسرت الغنيمة والرفيق.'],dead:['أدركك المطاردون','انتهت الغارة قبل بلوغ المخبأ.']};
function render(){document.body.dataset.screen=s.screen;if(s.screen==='reward'){root.innerHTML=renderReward(s);return;}if(s.screen==='title'){root.innerHTML=`<main class="hero"><p class="eyebrow">الشنفرى</p><h1>طريق العودة</h1><div class="hero-art" aria-hidden="true"><span class="figure"></span></div><p>خذ الزاد. أخرج رفيقك.<br>واحتفظ بما يعيدكما حيَّين.</p>${btn('تعلّم بأول حركة','teach','primary')}${btn('ابدأ الغارة','start','secondary')}<small>مواجهتان · مكافأة تكسر القواعد · ٦ بطاقات</small></main>`;return;}if(s.screen==='end'){const [title,text]=results[s.outcome]||results.dead;root.innerHTML=`<main class="hero"><p class="eyebrow">${s.campaign?'انتهت الجولة · مواجهة '+num(s.encounter)+' من ٢':'انتهت الغارة'} · ${num(s.turn)} أدوار</p><h1>${title}</h1><p>${text}</p><div class="result-stats"><span>الصحة ${ratio(s.hp,16)}</span><span>الزاد: ${s.loot?'معك':'ضاع'}</span><span>الرفيق: ${s.rescue>=3&&s.friendHp>0?'معك':s.friendHp>0?'خلفك':'سقط'}</span></div>${btn('تقرير الرن','report','primary')}${btn('غارة جديدة','restart','secondary')}${btn('القائمة','help','secondary')}</main>`;return;}root.innerHTML=renderGame(s,{pending,lesson,feedback});}
function reset(teach=false){if(menu.open)menu.close();if(choice.open)choice.close();s=fresh(true);s.screen='play';runReport=beginReport(s,{tutorial:teach});selection=null;pending=null;feedback='';lesson=teach?0:4;persist();render();focus(teach?'[data-card="run"]':'[data-card]:not(:disabled)');}
function selectAction(name){returnFocus=`[data-action="${name}"]`;selection=null;pending=name.startsWith('assist-')?{type:'assist',target:name.split('-')[1]}:{type:name};render();renderChoice();openChoice();}
function action(name){if(name==='inspect-relic'&&s.relic){info(relics[s.relic].name,relics[s.relic].rule);return;}if(name==='report'){showReport(runReport);return;}if(name==='last-report'){try{const last=JSON.parse(localStorage.getItem(LAST_REPORT));if(last)showReport(last);else info('لا يوجد تقرير بعد','أكمل جولة بعد هذا التحديث لتسجيل قراراتها.');}catch{info('لا يوجد تقرير بعد','أكمل جولة جديدة لبدء التسجيل.');}return;}if(name==='copy-report'){copyReport();return;}if(name==='download-report'){downloadReport();return;}if(name==='close'){menu.close();focus('[data-action="help"]');return;}if(name==='help'){help();return;}if(name==='teach'){reset(true);return;}if(name==='restart'){reset(false);return;}if(name==='skip'){lesson=4;feedback='';persist();render();return;}if(name==='cancel'){dismiss();return;}if(name==='confirm'&&pending){dispatch(pending);return;}if(name==='start'){s=apply(s,{type:'start'});runReport=beginReport(s,{tutorial:lesson<4});persist();render();focus('[data-card="run"]');return;}if(name==='assistance'){selection=null;pending=null;choice.innerHTML=`<div class="sheet-header"><h2>مساندة واحدة</h2>${btn('×','cancel','icon-button')}</div><p>رفيقك معك. اختر مساعدته؛ لا تستهلك فعلًا.</p>${btn('تقدم خطوة إضافية','assist-move')}${btn('احجب ٣ ضرر هذا الدور','assist-block')}`;openChoice();return;}if(['step','retreat','drop','assist-move','assist-block'].includes(name)){selectAction(name);return;}if(name==='end'){if(s.ap>0)selectAction(name);else dispatch({type:'end'});return;}if(name==='alarm'){info('الإنذار',`مستواه الآن ${ratio(s.alarm,6)}. يضيف ${num(Math.floor(s.alarm/3))} ضررًا للهجوم. يزيد ١ بنهاية كل دور. «تضليل» يخفضه ٢.`);return;}if(name==='inspect-loot'&&s.phase==='duel'){info('الزاد',s.loot?'احتفظت به من الغارة الأولى. حمله يجعل العَدْو خطوتين بدل ٣.':'خرجت من الغارة الأولى بلا زاد. هدفك هنا هزيمة الحارس أو عبور الممر.');return;}if(name==='inspect-loot'){info('الزاد',s.loot?'معك الآن. حمله يجعل بطاقة العَدْو تتقدم خطوتين بدل ٣.':s.lootLost?'ابتعدت القافلة. يمكنك إنقاذ رفيقك أو العودة.':s.phase==='approach'?'أولًا، اقطع الطريق إلى القافلة.':'تحتاج ٤ تقدم لأخذه. «عَدْو» أو الخطوة بلا بطاقة تقرّبك. الحامل يبتعد خطوة بنهاية الدور إن لم تعطّله بسهم.');return;}if(name==='inspect-friend'&&s.phase==='duel'&&s.rescue<3){info('رفيقك','لم يخرج معك من الغارة الأولى. تواجه حارس الممر وحدك.');return;}if(name==='inspect-friend'){info('رفيقك',s.rescue>=3?'معك. يمنحك مساندة واحدة: خطوة إضافية أو حجب ٣ ضرر.':s.phase==='approach'?'يتقدم من الجهة الأخرى. ستلقاه عند القافلة.':s.phase==='retreat'?'بدأت العودة وتركته عند القافلة.':'يحتاج ٣ تحرير ليخرج معك. «نصل» يقطع القيد و«تغطية» تحمي خروجه.');return;}if(name==='inspect-guard'&&s.phase==='duel'){info('حارس الممر','قوته '+num(s.guards)+'. أنقصها إلى صفر بالسهم والنصل، أو أكمل ٦ تقدم لعبور الممر. ضربه يخفف ضرر هجومه.');return;}if(name==='inspect-guard'){info(s.phase==='retreat'?'المطاردون':'الحرس',s.phase==='retreat'?'الضرر الأساسي ٢، ويزيد مع الإنذار. احمِ نفسك وأكمل ٦ تقدم للوصول للمخبأ.':`قوتهم ${num(s.guards)}. «سهم» ينقصها ٢ و«نصل» ينقصها ٣. أثناء الغارة يزيد ضرر الهجوم مع قوة الحرس. لا يلزم قتلهم لأخذ الزاد.`);}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.action){action(b.dataset.action);return;}if(b.dataset.relic&&s.screen==='reward'){returnFocus='[data-relic="'+b.dataset.relic+'"]';selection=null;pending={type:'relic',relic:b.dataset.relic};renderChoice();openChoice();return;}if(b.dataset.card){showCard(b.dataset.card);return;}if(b.dataset.target&&selection){pending={type:'play',card:selection,target:b.dataset.target};render();renderChoice();choice.querySelector('[data-action="confirm"]')?.focus({preventScroll:true});}});
choice.addEventListener('cancel',e=>{e.preventDefault();dismiss();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!choice.open&&!menu.open){dismiss();return;}if(choice.open||menu.open)return;if(e.key>='1'&&e.key<='6'&&!e.ctrlKey&&!e.metaKey){const b=root.querySelectorAll('[data-card]')[Number(e.key)-1];if(b&&!b.disabled)b.click();}});
render();focus(s.screen==='title'?'[data-action="teach"]':'[data-card]:not(:disabled)');
